        return lockedBy;
    }

    /** Lock the claim to a user's editor, or release it (null). */
    public void setLockedBy(String lockedBy) {
        this.lockedBy = lockedBy;
    }

    /** Whether the claim is locked by a user other than this one. */
    public boolean lockedAgainst(String user) {
        return lockedBy != null && !lockedBy.equals(user);
    }

    /** Count one more proof added to the claim. */
    public void addProof() {
        this.proofs++;
    }

    /** Whether the claim is deferred on a day: it is OPEN and that day is before its deferred-until
     *  date. From that date on it is an OPEN claim like any other. */
    public boolean deferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today.isBefore(deferredUntil);
    }

    /** Whether the claim counts toward what is claimed and due: only OPEN, PENDING and SETTLED ones do. */
    public boolean counts() {
        return status.counts();
    }

    /** Whether the claim is held: it is OPEN and dated within one of its person's holds. */
    public boolean heldBy(List<PersonHold> holds) {
        return status == ClaimStatus.OPEN && holds.stream().anyMatch(hold -> hold.contains(date));
    }

    /** Whether the claim is left out for its person's retirement: it is OPEN or PENDING and the
     *  sheet's today is on or after the date they are retired from (null: not retired). */
    public boolean retiredOn(LocalDate retiredFrom, LocalDate today) {
        return status.isOpen() && retiredFrom != null && !today.isBefore(retiredFrom);
    }

    /** Whether the claim counts in live totals on the sheet's today given its person's holds and
     *  retirement date: one that counts and is not deferred, unless it is held, or OPEN or PENDING once
     *  its person is retired, and not bound by a statement (a bound claim stays in whatever its date). */
    public boolean countsLive(List<PersonHold> holds, LocalDate retiredFrom, LocalDate today) {
        return counts() && !deferredOn(today) && (stated || !(heldBy(holds) || retiredOn(retiredFrom, today)));
    }

    /** Whether the claim counts in a period's live figures, given the status it had at the end of the
     *  period's last day (null when it was added after): that status counts, and the live rules leave
     *  it in (not deferred on the sheet's today, and not held or retired out unless bound by a statement). */
    public boolean countsAsOf(ClaimStatus then, List<PersonHold> holds, LocalDate retiredFrom, LocalDate today) {
        return then != null && then.counts() && !deferredOn(today)
                && (stated || !(heldBy(holds) || retiredOn(retiredFrom, today)));
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; an OPEN claim a clerk settles above
 *  the clerk limit is PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
 *  DRAFT, OPEN or PENDING claim can be VOID, and a steward may void a SETTLED one within 7 days of
 *  its settlement. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether the claim counts toward what is claimed and due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether the claim is open: OPEN, or PENDING an approval. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may be moved to another person: a SETTLED or VOID one cannot. */
    public boolean canReassign() {
        return this == DRAFT || this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may be opened, settled or voided to the given one; a PENDING
     *  claim leaves PENDING only by being approved, rejected or voided. */
    public boolean canMoveTo(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case PENDING, DRAFT -> false;
        };
    }
}
package net.officefloor.hq.app.claim;

import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Component;

/** Puts a selection of a sheet's claims in list order: people in the order they were added, each
 *  person's claims newest first. */
@Component
public class ClaimListOrder {

    private final ClaimRepository claims;
    private final PersonRepository people;

    public ClaimListOrder(ClaimRepository claims, PersonRepository people) {
        this.claims = claims;
        this.people = people;
    }

    /** The selected claims on the sheet, in list order; an id not on the sheet is left out. */
    public List<Claim> selected(String sheetId, Set<Long> ids) {
        Map<Long, Integer> personOrder = new HashMap<>();
        List<Person> sheetPeople = people.findBySheetIdOrderByIdAsc(sheetId);
        for (int i = 0; i < sheetPeople.size(); i++) {
            personOrder.put(sheetPeople.get(i).getId(), i);
        }
        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
                .filter(claim -> ids.contains(claim.getId()))
                .sorted(Comparator.comparing((Claim claim) -> personOrder.getOrDefault(claim.getPersonId(), Integer.MAX_VALUE)))
                .toList();
    }
}
package net.officefloor.hq.app;

import java.time.LocalDate;

/** The as-of date a user's screen is set to: while it is set, everything the screen reads is as it
 *  stood at the end of that day and every change is refused. It belongs to the screen, which sends it
 *  in a header with each request; a request without it reads the sheet as it is now. */
public final class AsOf {

    /** The header carrying the screen's as-of date (yyyy-mm-dd). */
    public static final String HEADER = "X-As-Of";

    private AsOf() {
    }

    /** The as-of date a header carries; null when it is absent or blank (the screen shows now). */
    public static LocalDate parse(String header) {
        return header == null || header.isBlank() ? null : LocalDate.parse(header.trim());
    }
}

