309	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
310	        if (to == ClaimStatus.SETTLED) {
311	            line += " due=" + settledDueText(saved);
312	        } else if (reversing) {
313	            line += " reversed=" + settledDueText(saved);
314	        }
315	        if (to == ClaimStatus.VOID && reason != null) {
316	            line += " reason=" + reason;
317	        }
318	        audit.recordOnCommit(line);
319	        if (to == ClaimStatus.SETTLED) {
320	            notifyWatchers(sheetId, user, person, saved);
321	        }
322	        return saved;
323	    }
