350	    /** Split an amount off an OPEN claim: it keeps the rest of its amount and loses any figure a
351	     *  statement bound it to, and a new OPEN claim of the split-off amount, with the same date and
352	     *  note, the next number, opened by the user and due by its date plus the terms in force on it,
353	     *  is listed under the person naming the claim it was split from (a late entry when its due-by falls
354	     *  in a soft-closed period). A claim that is not OPEN, one
355	     *  deferred, one dated in a closed period, an amount not above 0.00 and below the claim's, or a
356	     *  user whose role may not open a claim, is refused. */
357	    @Transactional
358	    public Split split(String sheetId, String user, Long personId, Long id, BigDecimal amount) {
359	        Person person = person(sheetId, personId);
360	        // Lock the sheet first, as opening does: the new claim takes the next number.
361	        sheets.lock(sheetId);
362	        Claim claim = claim(sheetId, personId, id);
363	        settings.refuseUnless(sheetId, user, Permission.OPEN);
364	        refuseClosed(sheetId, claim.getDueBy());
365	        if (claim.getStatus() != ClaimStatus.OPEN || claim.deferredOn(sheets.today(sheetId))) {
366	            throw new SplitRefusedException("A " + claim.getStatus() + " claim cannot be split");
367	        }
368	        BigDecimal part = scaled(amount);
369	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
370	            throw new SplitRefusedException("A claim is split by an amount above 0.00 and below its own");
371	        }
372	        claim.setAmount(claim.getAmount().subtract(part));
373	        claim.unbind();
374	        Claim kept = claims.saveAndFlush(claim);
375	        LocalDate on = kept.getDate();
376	        int terms = termsFor(sheetId, person, on);
377	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
378	        Claim split = Claim.splitOff(kept, part, dueBy, terms, nextNumber(sheetId, dueBy), user);
379	        if (periods.softClosedOn(sheetId, dueBy)) {
380	            split.markLateEntry();
381	        }
382	        Claim added = claims.saveAndFlush(split);
383	        log(sheetId, user, person, added);
384	        audit.recordOnCommit(line("CLAIM_SPLIT", sheetId, user, person, kept, kept.getNumber())
385	                + " into=" + added.getNumber());
386	        record("CLAIM_OPENED", sheetId, user, person, added);
387	        return new Split(kept, added);
388	    }
