390	    /** A steward approves a PENDING claim: it is SETTLED, its due frozen at this moment. Anyone else,
391	     *  the user who opened or last edited it, or a claim that is not PENDING, is refused. */
392	    @Transactional
393	    public Claim approve(String sheetId, String user, Long personId, Long id) {
394	        Person person = person(sheetId, personId);
395	        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.SETTLED);
396	        if (claim.openedOrEditedBy(user)) {
397	            throw new OwnClaimSettleRefusedException(user);
398	        }
399	        BigDecimal due = dueOf(sheetId, person, claim);
400	        refuseUnproved(sheetId, person, claim, due);
401	        claim.setSettledDue(due);
