494	    /** A steward re-settles a SETTLED claim: its settled due is frozen again at the figure it would
495	     *  have today as an OPEN claim bound by no statement (today's rates, grades, floor and late
496	     *  charge), and its status log gains a SETTLED line. Anyone else, a claim that is not SETTLED, or
497	     *  one dated in a closed period, is refused. */
498	    @Transactional
499	    public Claim resettle(String sheetId, String user, Long personId, Long id) {
500	        Person person = person(sheetId, personId);
501	        Claim claim = claim(sheetId, personId, id);
502	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
503	            throw new ResettleRefusedException(user);
504	        }
505	        if (claim.getStatus() != ClaimStatus.SETTLED) {
506	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
507	        }
508	        refuseClosed(sheetId, claim.getDueBy());
509	        String old = settledDueText(claim);
510	        BigDecimal figure = liveFigureOf(sheetId, person, claim, null, null);
511	        claim.setSettledDue(figure == null ? null
512	                : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, person, claim, figure, true, null)), null));
513	        Claim saved = claims.saveAndFlush(claim);
514	        log(sheetId, user, person, saved);
515	        audit.recordOnCommit(line("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber())
516	                + " old=" + old + " new=" + settledDueText(saved));
517	        notifyWatchers(sheetId, user, person, saved);
518	        return saved;
519	    }
