539	    private Claim move(String sheetId, String user, Long personId, Long id, Long toPersonId, boolean samePerson) {
540	        Person from = person(sheetId, personId);
541	        Person to = person(sheetId, toPersonId);
542	        Claim claim = claim(sheetId, personId, id);
543	        if (!settings.allows(sheetId, user, Permission.REASSIGN)) {
544	            throw new ReassignRefusedException(user);
545	        }
546	        if (!claim.getStatus().canReassign()) {
547	            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
548	        }
549	        if (!samePerson && from.getId().equals(to.getId())) {
550	            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
551	        }
552	        if (claim.isCorrection()) {
553	            throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
554	        }
555	        refuseClosed(sheetId, claim.getDueBy());
556	        refuseRetired(to, claim.getDate());
557	        claim.setPersonId(to.getId());
558	        claim.unbind();
559	        claims.saveAndFlush(claim);
560	        claims.relist(claim.getId());
561	        Claim saved = claim(sheetId, to.getId(), id);
562	        audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
563	                + " from=" + from.getName() + " to=" + to.getName());
564	        return saved;
565	    }
