574	        // Lock the sheet first, as opening does: the claim may take the next number.
575	        sheets.lock(sheetId);
576	        Claim claim = claim(sheetId, personId, id);
577	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
578	            throw new RedateForbiddenException(user);
579	        }
580	        if (!claim.getStatus().isOpen()) {
581	            throw new RedateRefusedException("A " + claim.getStatus() + " claim cannot be re-dated");
582	        }
