643	    private void refuseLateOrUnstewardedVoid(String sheetId, String user, Claim claim) {
644	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
645	            throw new VoidRefusedException(user + " is not a steward: only a steward voids a settled claim");
646	        }
647	        LocalDate settledOn = logs.findByClaimIdOrderByIdAsc(claim.getId()).stream()
648	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
649	                .map(ClaimLogEntry::getOn)
650	                .reduce((first, last) -> last)
651	                .orElseThrow(() -> new VoidRefusedException("Claim " + claim.getId() + " has no settlement"));
652	        if (sheets.today(sheetId).isAfter(settledOn.plusDays(VOID_WINDOW_DAYS))) {
653	            throw new VoidRefusedException("A settled claim is voided within " + VOID_WINDOW_DAYS
654	                    + " days of its settlement on " + settledOn);
655	        }
656	    }
