681	    /** The number a claim opened now takes: under period numbering (set, and the sheet's today on or
682	     *  after it) the next within the period its due-by falls in, <period>-<n>, or X-<n> when it falls
683	     *  in none; otherwise the sheet's next sheet-wide number. Taken with the sheet locked. */
684	    private String nextNumber(String sheetId, LocalDate date) {
685	        if (!periodNumbering(sheetId)) {
686	            return String.valueOf(sheets.nextClaimNumber(sheetId));
687	        }
688	        String prefix = periodPrefixOf(sheetId, date);
689	        long last = Stream.concat(claims.numbers(sheetId).stream(), claims.retiredNumbers(sheetId).stream())
690	                .filter(number -> number.startsWith(prefix))
691	                .map(number -> number.substring(prefix.length()))
692	                .filter(n -> n.matches("\\d{1,18}"))
693	                .mapToLong(Long::parseLong)
694	                .max().orElse(0);
695	        return prefix + (last + 1);
696	    }
