698	    /** Whether period numbering is on: set, and the sheet's today on or after it. */
699	    private boolean periodNumbering(String sheetId) {
700	        LocalDate from = settings.periodNumberingFrom(sheetId);
701	        return from != null && !sheets.today(sheetId).isBefore(from);
702	    }
