746	    /** The due a claim would show were a grade's rate the one given on every date (null: as the rates
747	     *  stand). */
748	    private BigDecimal dueOf(String sheetId, Person person, Claim claim, LocalDate asOf, RateOverride override) {
749	        if (claim.getSettledDue() != null) {
750	            return claim.getSettledDue();
751	        }
752	        BigDecimal figure = figureOf(sheetId, person, claim, asOf, override);
753	        boolean open = claim.getStatus().isOpen() && !claim.deferredOn(todayOr(sheetId, asOf));
754	        return figure == null ? null
755	                : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, person, claim, figure, open, asOf)), asOf);
756	    }
