758	    /** The day that stands for the sheet's today: the given one, else the sheet's today. */
759	    private LocalDate todayOr(String sheetId, LocalDate asOf) {
760	        return asOf != null ? asOf : sheets.today(sheetId);
761	    }
762	
763	    /** A due raised to the sheet's floor in force on the claim's date, unless the claim is a correction. */
764	    private BigDecimal floored(String sheetId, Claim claim, BigDecimal due, LocalDate asOf) {
765	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate(), asOf));
766	    }
767	
768	    /** The date a claim is overdue after: its due-by plus the grace days in force on its date for the
769	     *  person's grade in force on its date (as they stood at the end of a day; null: as they stand now). */
770	    public LocalDate overdueFrom(String sheetId, Person person, Claim claim, LocalDate asOf) {
771	        String grade = grades.gradeOn(person.getId(), claim.getDate(), asOf);
772	        return claim.getDueBy().plusDays(settings.graceFor(sheetId, grade, claim.getDate(), asOf));
773	    }
774	
775	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by
776	     *  plus its grace, see overdueFrom, is before the sheet's today) or a correction, else the late percent of
777	     *  the figure for every 30-day boundary it is overdue past (its due-by plus its grace plus 30, 60, 90 ...
778	     *  days), compounding: the late percent in force on that boundary date of the figure plus the charges
779	     *  of the boundaries before it, rounded to two decimals as the claim's date decides (see roundingOf), the
780	     *  charges added up. Never bound by a statement: it follows the
781	     *  sheet's today. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
782	     *  claim as if it were still OPEN. */
783	    private BigDecimal lateChargeOf(String sheetId, Person person, Claim claim, BigDecimal figure, boolean open,
784	            LocalDate asOf) {
785	        BigDecimal none = BigDecimal.ZERO.setScale(2);
786	        if (!open || claim.isCorrection()) {
787	            return none;
788	        }
789	        LocalDate from = overdueFrom(sheetId, person, claim, asOf);
790	        long days = ChronoUnit.DAYS.between(from, todayOr(sheetId, asOf));
791	        if (days < 30) {
792	            return none;
793	        }
794	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
795	        BigDecimal charge = none;
796	        for (long boundary = 1; boundary <= days / 30; boundary++) {
797	            BigDecimal pct = settings.latePct(sheetId, from.plusDays(30 * boundary), asOf);
798	            if (pct.signum() != 0) {
799	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
800	            }
801	        }
802	        return charge;
803	    }
804	
805	    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
806	     *  on the claim's date: amount times rate
807	     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf); the floor is
808	     *  not applied here (see dueOf); null when no rate applies. */
809	    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim, LocalDate asOf,
810	            RateOverride override) {
811	        BigDecimal amount = claim.getAmount();
812	        RoundingMode rounding = roundingOf(sheetId, claim, asOf);
813	        String grade = grades.gradeOn(person.getId(), claim.getDate(), asOf);
814	        Optional<BigDecimal> inForce = override != null && override.grade().equals(grade) ? Optional.of(override.rate())
815	                : rates.rateOn(sheetId, grade, claim.getDate(), asOf).map(Rate::getRate);
816	        return inForce
817	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
818	                .orElse(null);
819	    }
820	
821	    /** A grade's rate taken to apply on every date in place of the rates set for it. */
822	    private record RateOverride(String grade, BigDecimal rate) {
823	    }
824	
825	    /** What a rate preview finds: how many claims would show a different due, and the sum of the
826	     *  differences (new due minus current due). */
827	    public record RatePreview(int count, BigDecimal diff) {
828	    }
829	
830	    /** How the OPEN and PENDING claims of people on a grade (the grade in force on the claim's date)
831	     *  would change were the rate given the grade's rate on every date: how many would show a different
832	     *  due and the sum of the differences (a due of n/a counts as 0.00). A claim a statement binds keeps
833	     *  its figure. Nothing is saved. */
834	    @Transactional(readOnly = true)
835	    public RatePreview previewRate(String sheetId, String grade, BigDecimal rate) {
836	        RateOverride override = new RateOverride(grade, rate);
837	        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
838	                .collect(Collectors.toMap(Person::getId, person -> person));
839	        int count = 0;
840	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
841	        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
842	            Person person = byId.get(claim.getPersonId());
843	            if (person == null || !claim.getStatus().isOpen()
844	                    || !grade.equals(grades.gradeOn(person.getId(), claim.getDate(), null))) {
845	                continue;
846	            }
847	            BigDecimal now = dueOf(sheetId, person, claim, null);
848	            BigDecimal then = dueOf(sheetId, person, claim, null, override);
849	            BigDecimal was = now == null ? BigDecimal.ZERO : now;
850	            BigDecimal will = then == null ? BigDecimal.ZERO : then;
851	            if ((now == null) != (then == null) || was.compareTo(will) != 0) {
852	                count++;
853	                diff = diff.add(will.subtract(was));
854	            }
855	        }
856	        return new RatePreview(count, diff.setScale(2, RoundingMode.HALF_UP));
857	    }
858	
859	    /** The date a claim's live figures round by: its own, or for a correction the date of the claim
860	     *  it corrects. */
861	    public LocalDate roundsBy(String sheetId, Claim claim) {
862	        if (!claim.isCorrection() || claim.getCorrects() == null) {
863	            return claim.getDate();
864	        }
865	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects())
866	                .map(Claim::getDate).orElse(claim.getDate());
867	    }
868	
869	    /** How a claim's live figures round: by the sheet's policy date against the date it rounds by. */
870	    private RoundingMode roundingOf(String sheetId, Claim claim, LocalDate asOf) {
871	        return settings.roundingOn(sheetId, roundsBy(sheetId, claim), asOf);
872	    }
873	
874	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit; a due of n/a
875	     *  is within any limit, and a steward settles anything. */
876	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
877	        BigDecimal limit = settings.clerkLimit(sheetId);
878	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
879	            return false;
880	        }
881	        return settings.roleOf(sheetId, user) == Role.CLERK;
882	    }
883	
884	    /** A claim whose due is above the proof threshold in force on its date (its person's grade's in
885	     *  force then when one is set, else the sheet's) cannot be settled or approved while it has no
886	     *  proofs; a due of n/a, or no threshold, asks for none. */
887	    private void refuseUnproved(String sheetId, Person person, Claim claim, BigDecimal due) {
888	        String grade = grades.gradeOn(person.getId(), claim.getDate());
889	        BigDecimal threshold = settings.proofThresholdFor(sheetId, grade, claim.getDate());
890	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
891	            throw new ProofRequiredException(due, threshold);
892	        }
893	    }
894	
895	    /** A claim whose due is above the note threshold in force on its date cannot be opened while its
896	     *  note is empty; a due of n/a, or no threshold, asks for none. */
897	    private void refuseUnnoted(String sheetId, Person person, Claim claim) {
898	        BigDecimal threshold = settings.noteThreshold(sheetId, claim.getDate());
899	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
900	            return;
901	        }
902	        BigDecimal due = dueOf(sheetId, person, claim);
903	        if (due != null && due.compareTo(threshold) > 0) {
904	            throw new NoteRequiredException(due, threshold);
905	        }
906	    }
907	
908	    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
909	     *  any other amount names none. */
910	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
911	        if (amount.signum() >= 0) {
912	            if (corrects != null) {
913	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
914	            }
915	            return;
916	        }
917	        if (corrects == null) {
918	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
919	        }
920	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
921	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
922	        if (!settled) {
923	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
924	        }
925	    }
926	
927	    /** Whether a claim on the sheet other than the given one (null: any) already uses the reference,
928	     *  without regard to case; a null reference is never in use. */
929	    public boolean refInUse(String sheetId, String ref, Long exceptId) {
930	        return ref != null && claims.refInUse(sheetId, Claim.keyOf(ref), exceptId);
931	    }
932	
933	    /** A reference another claim on the sheet already uses cannot be given again. */
934	    private void refuseRefInUse(String sheetId, String ref, Long exceptId) {
935	        if (refInUse(sheetId, ref, exceptId)) {
936	            throw new RefInUseException("The reference " + ref + " is already used on the sheet");
937	        }
938	    }
939	
940	    /** A claim whose due-by falls inside a closed period cannot be added, edited, opened, settled or voided. */
941	    private void refuseClosed(String sheetId, LocalDate dueBy) {
942	        if (periods.closedOn(sheetId, dueBy)) {
943	            throw new PeriodClosedException("A claim due by " + dueBy + " falls in a closed period");
944	        }
945	    }
946	
947	    /** A claim dated after its person's retirement date cannot be added or moved there. */
948	    private static void refuseRetired(Person person, LocalDate date) {
949	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
950	            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
951	        }
952	    }
953	
954	    private Person person(String sheetId, Long personId) {
955	        return people.findByIdAndSheetId(personId, sheetId)
956	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
957	    }
958	
959	    /** One NOTIFY line for each user watching the claim's person, in the order they started watching. */
960	    private void notifyWatchers(String sheetId, String user, Person person, Claim claim) {
961	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
962	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
963	                    + " person=" + person.getName() + " number=" + claim.getNumber());
964	        }
965	    }
966	
967	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
968	        record(event, sheetId, user, person, claim, claim.getNumber());
969	    }
970	
971	    /** One audit line about a claim; a claim with a number carries it at the end. */
972	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number) {
973	        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
974	    }
975	
976	    private static String line(String event, String sheetId, String user, Person person, Claim claim, String number) {
977	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
978	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
979	                + (number != null ? " number=" + number : "");
980	    }
981	
982	    private static BigDecimal scaled(BigDecimal amount) {
983	        return amount.setScale(2, RoundingMode.UNNECESSARY);
984	    }
985	
986	    /** A claim number as typed: trimmed, null when blank. */
987	    private static String numberOf(String number) {
988	        return number == null || number.isBlank() ? null : number.trim();
989	    }
990	
991	    /** Tags as typed, comma separated: each trimmed and in lower case, blanks and repeats dropped,
992	     *  sorted. */
993	    public static SortedSet<String> tagsOf(String tags) {
994	        SortedSet<String> out = new TreeSet<>();
995	        if (tags != null) {
996	            for (String tag : tags.split(",")) {
997	                if (!tag.isBlank()) {
998	                    out.add(tag.trim().toLowerCase(Locale.ROOT));
999	                }
1000	            }
1001	        }
1002	        return out;
1003	    }
1004	
1005	    /** Every tag ever used on the sheet, sorted. */
1006	    public List<String> tagsUsed(String sheetId) {
1007	        return claims.tagsUsed(sheetId);
1008	    }
1009	
1010	    /** Keep the claim's tags on the sheet's list of the tags ever used. */
1011	    private void useTags(String sheetId, Claim claim) {
1012	        claim.getTags().forEach(tag -> claims.useTag(sheetId, tag));
1013	    }
1014	
1015	    /** An external reference as typed: trimmed, null when blank. */
1016	    public static String refOf(String ref) {
1017	        return ref == null || ref.isBlank() ? null : ref.trim();
1018	    }
1019	
1020	    private static String noteOf(String note) {
1021	        return note == null ? "" : note.trim();
1022	    }
1023	
1024	    /** The terms in business days a claim of the person dated on a date takes: the person's own, else their
1025	     *  grade's in force then, else the sheet's. */
1026	    private int termsFor(String sheetId, Person person, LocalDate on) {
1027	        return person.getTerms() != null ? person.getTerms()
1028	                : settings.termsFor(sheetId, grades.gradeOn(person.getId(), on), on);
1029	    }
1030	}
