610	/**
611	 * A viewer sees every screen and figure and can change nothing: every request that would change a
612	 * sheet is refused (403) before it reaches its controller, so it writes nothing to the store or the
613	 * audit. Loading a sheet changes nothing and is let through; so are the bulk actions, which a
614	 * viewer takes with nothing done (every selected item refused, see the bulk services).
615	 */
616	@Component
617	public class ViewerGuard implements HandlerInterceptor {
618	
619	    /** The sheet-scoped requests the guard watches. */
620	    public static final String PATTERN = "/api/sheets/{sheetId}/**";
621	
622	    /** The requests a viewer may make: loading a sheet, and the bulk actions that refuse every item. */
623	    private static final Set<String> LET_THROUGH = Set.of(
624	            "/api/sheets/{sheetId}/load",
625	            "/api/sheets/{sheetId}/claims/open",
626	            "/api/sheets/{sheetId}/claims/settle",
627	            "/api/sheets/{sheetId}/claims/reassign",
628	            "/api/sheets/{sheetId}/people/grade");
629	
630	    private final AntPathMatcher paths = new AntPathMatcher();
631	    private final SettingService settings;
632	
633	    public ViewerGuard(SettingService settings) {
634	        this.settings = settings;
635	    }
636	
637	    @Override
638	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
639	        String method = request.getMethod();
640	        if (HttpMethod.GET.matches(method) || HttpMethod.HEAD.matches(method) || HttpMethod.OPTIONS.matches(method)) {
641	            return true;
642	        }
643	        String path = request.getRequestURI().substring(request.getContextPath().length());
644	        if (!paths.match(PATTERN, path) || LET_THROUGH.stream().anyMatch(p -> paths.match(p, path))) {
645	            return true;
646	        }
647	        String header = request.getHeader(SignedInUser.HEADER);
648	        if (header == null || header.isBlank()) {
649	            return true;
650	        }
651	        Map<String, String> vars = paths.extractUriTemplateVariables(PATTERN, path);
652	        String sheetId = URLDecoder.decode(vars.get("sheetId"), StandardCharsets.UTF_8).trim();
653	        if (settings.isViewer(sheetId, SignedInUser.decode(header))) {
654	            response.setStatus(HttpStatus.FORBIDDEN.value());
655	            return false;
656	        }
657	        return true;
658	    }
