export const GRADES = ['A', 'B', 'C'];

/** Shown for a due that has no rate to work from. */
export const NO_RATE = 'n/a';

/** The due on an amount in cents at a percent rate (two decimals), in cents: amount times rate
 *  divided by 100, rounded half up when `halfUp`, else half to even (a negative amount rounds as its
 *  opposite does). Worked in whole numbers so nothing is lost to floating point. */
export function dueCents(amountCents: number, rate: string, halfUp: boolean): number {
  if (amountCents < 0) return -dueCents(-amountCents, rate, halfUp);
  const hundredths = BigInt(Math.round(Number(rate) * 100));
  const product = BigInt(amountCents) * hundredths;
  const whole = product / 10000n;
  const rest = product % 10000n;
  return Number(rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole);
}

/** The rate in force on a date among a grade's rates: the one whose from-date is the latest on or
 *  before the date (no from-date applies from the beginning of time); null when none applies, or
 *  when that one's to-date is before the date. */
export function rateOn(rates: Rate[], date: string): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.from !== null && r.from > date) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  if (best?.to && best.to < date) return null;
  return best?.rate ?? null;
}

/** A grade a person was given, in force from its from-date. */
export interface PersonGrade {
  grade: string;
  /** The date the grade applies from (yyyy-mm-dd); null when it applies from the beginning of time,
   *  as the first grade a person was given does. */
  from: string | null;
}

/** The grade in force on a date among a person's grades: the one whose from-date is the latest on
 *  or before the date; null when none applies. */
export function gradeOn(grades: PersonGrade[], date: string): string | null {
  let best: PersonGrade | null = null;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (best === null || (best.from ?? '') < (g.from ?? '')) best = g;
  }
  return best?.grade ?? null;
}

/** Rates in the order they are listed: by grade, then from the earliest. */
function byGradeAndFrom(a: Rate, b: Rate): number {
  return a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '');
}

/** How a candidate rate would change the dues of a grade's open claims. */
export interface RatePreview {
  /** How many OPEN and PENDING claims would show a different due. */
  count: number;
  /** The sum of the differences (new due minus current due), two decimals. */
  diff: string;
}

const PERCENT = /^\d{1,5}(\.\d{1,2})?$/;

// The active sheet's rates for each grade, each from its from-date, re-read whenever a sheet is
// loaded.
@Injectable({ providedIn: 'root' })
export class RateStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's rates by grade, each grade's from the earliest. */
  readonly rates = signal<Rate[]>([]);
  /** Each grade's rates by grade; a grade with no rate is absent. */
  readonly byGrade = computed(() => {
    const map = new Map<string, Rate[]>();
    for (const r of this.rates()) map.set(r.grade, [...(map.get(r.grade) ?? []), r]);
    return map;
  });
  /** Each grade's rate in force on the sheet's today; a grade with none is absent. */
  readonly current = computed(() => {
    const today = this.session.today();
    const map = new Map<string, string>();
    if (!today) return map;
    for (const [grade, rates] of this.byGrade()) {
      const rate = rateOn(rates, today);
      if (rate !== null) map.set(grade, rate);
    }
    return map;
  });

  /** A grade's rates; none when the grade has no rate. */
  of(grade: string): Rate[] {
    return this.byGrade().get(grade) ?? [];
  }

  /** The rates of a person's grade in force on a date; none when that grade has no rate. */
  ofGradeOn(grades: PersonGrade[], date: string): Rate[] {
    const grade = gradeOn(grades, date);
    return grade === null ? [] : this.of(grade);
  }

  constructor() {
    effect(() => {
      const sheet = this.session.sheetId();
      const load = this.session.loads();
      this.rates.set([]);
      if (sheet) void this.read(sheet, load);
    });
  }
  { action: 'reopen', label: 'Reopen a period', standing: 'steward' },
];

/** Whether a permission entry is blank or a comma separated list of roles. */
function rolesList(typed: string): boolean {
  return typed === '' || typed.split(',').every((r) => ROLES.includes(r.trim()));
}

// The active sheet's settings, re-read whenever a sheet is loaded.
@Injectable({ providedIn: 'root' })
export class SettingStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly roles = signal<RoleView[]>([]);
  readonly delegations = signal<DelegationView[]>([]);
  /** Every value recorded for the dated settings, by key. */
  readonly dated = signal<Record<string, DatedValue[]>>({});
  /** The clerk limit in force on the sheet's today; null when there is none. */
  readonly clerkLimit = computed(() => this.onToday('clerk-limit') ?? null);
  /** The floor in force on the sheet's today. */
  readonly floor = computed(() => this.onToday('floor') ?? FLOOR);
  /** The cap in force on the sheet's today; null when there is none. */
  readonly cap = computed(() => this.onToday('cap') ?? null);
  /** The proof threshold in force on the sheet's today; null when there is none. */
  readonly proofThreshold = computed(() => this.onToday('proof-threshold') ?? null);
  /** The note threshold in force on the sheet's today; null when there is none. */
  readonly noteThreshold = computed(() => this.onToday('note-threshold') ?? null);
  /** The terms in force on the sheet's today. */
  readonly terms = computed(() => Number(this.onToday('terms') ?? TERMS));
  /** The late percent in force on the sheet's today. */
  readonly latePct = computed(() => this.onToday('late-pct') ?? LATE_PCT);
  /** The grades' own terms in force on the sheet's today, by grade; a grade not listed takes the
   *  sheet's terms. */
  readonly gradeTerms = computed(() => {
    const byGrade: Record<string, number> = {};
    for (const g of GRADES) {
      const days = this.onToday(`terms-${g}`);
      if (days !== undefined && days !== null) byGrade[g] = Number(days);
    }
    return byGrade;
  });
  /** The floor in force on a date: the least the live due of a claim of that date can be. */
  readonly floorOn = computed(() => {
    const recorded = this.dated()['floor'];
    return (date: string) => valueOn(recorded, date) ?? FLOOR;
  });
  /** The late percent in force on a date: what an overdue claim of that date gains. */
  readonly latePctOn = computed(() => {
    const recorded = this.dated()['late-pct'];
    return (date: string) => valueOn(recorded, date) ?? LATE_PCT;
  });
  /** The grace days in force on a date for a grade: a claim of that grade and date is overdue only once
   *  its due-by plus them is before the sheet's today; 0 when the grade has none then (blank). */
  readonly graceOn = computed(() => {
    const dated = this.dated();
    return (grade: string | null, date: string) => {
      if (grade === null) return 0;
      const days = valueOn(dated[`grace-${grade}`], date);
      return days === undefined || days === null ? 0 : Number(days);
    };
  });
  readonly policyDate = signal('');
  readonly periodNumberingFrom = signal('');
  readonly entryDate = signal('');
  /** The grace days as text: whole days, blank for off. */
  /** Each person's due-total for the period fixed when it was closed (two decimals), by person id;
   *  empty while it is open. */
  closedPersonTotals: Record<string, string>;
}

/** The period whose dates contain a date; null when none does. Periods never overlap, so at most
 *  one can. */
export function periodOf(periods: Period[], date: string): Period | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

const DATE = /^\d{4}-\d{2}-\d{2}$/;

